add_filter( 'comments_open', 'perfectpixel_force_product_reviews_open', 20, 2 );
add_filter( 'woocommerce_product_get_reviews_allowed', 'perfectpixel_force_product_reviews_allowed' );

function perfectpixel_force_product_reviews_open( $open, $post_id ) {
	return 'product' === get_post_type( $post_id ) && wc_reviews_enabled() ? true : $open;
}

function perfectpixel_force_product_reviews_allowed( $allowed ) {
	return wc_reviews_enabled() ? true : $allowed;
}
